gameActivityClassAdditions.insert:
public void LaunchFastGameStore(boolean openTheStorePage, String storeProductId, String storePublicKey)
{
	Intent intent = new Intent(GameActivity.this, FastGameStoreActivity.class);
	intent.putExtra("openTheStorePage", openTheStorePage);
	if (storeProductId != null)
	{
		if (storeProductId.length() > 0)
		{
			intent.putExtra("storeProductId", storeProductId);
		}
	}
	if (storePublicKey != null)
	{
		if (storePublicKey.length() > 0)
		{
			intent.putExtra("storePublicKey", storePublicKey);
		}
	}
	startActivity(intent);
}

buildGradleAdditions.insert:
repositories {
	google()
	jcenter()
	maven { url 'https://jitpack.io' }
}

android {
	defaultConfig {
		def marketApplicationId = "ir.mservices.market"
		def marketBindAddress = "ir.mservices.market.InAppBillingService.BIND"
		manifestPlaceholders = [marketApplicationId: "${marketApplicationId}",
			marketBindAddress: "${marketBindAddress}",
			marketPermission: "${marketApplicationId}.BILLING"]
	}
}

dependencies {
	implementation 'com.github.myketstore:myket-billing-client:1.6'
}
